<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Plus,Delete,Search} from '@element-plus/icons-vue'
import {api} from '../api'
const section=ref('company'),form=ref<any>(null),health=ref<any>({}),channels=ref<any[]>([]),memories=ref<any[]>([]),knowledge=ref<any>({items:[]}),graph=ref<any>({})
const testing=ref(false),saving=ref(false),testResult=ref<any>(null),memoryDialog=ref(false),knowledgeDialog=ref(false),memoryKind=ref('company'),memoryText=ref(''),knowledgeTitle=ref(''),knowledgeBody=ref(''),query=ref('')
const tracing=ref<any>({}),guides=ref<any[]>([])
const browser=ref<any>({}),browserUrl=ref(''),browserTesting=ref(false),browserResult=ref<any>(null)
const memoryLabels:Record<string,string>={company:'公司画像',preference:'偏好',exclusion:'排除项',recipes:'检索经验',feedback:'反馈',search_experience:'来源经验',company_memory:'企业档案'}
const stepLabels:Record<string,string>={intent:'理解需求',quick:'快速回复',context:'读取记忆',profile:'分析产品',plan:'规划渠道',decide:'选择渠道',search:'检索资料',read:'读取来源',extract:'核验客户',save:'保存客户',gap:'补查缺口',answer:'整理结果',learn:'更新经验',company_context:'读取历史研究',company_resolve:'确认企业',company_enrich:'核验工商资料',company_tenders:'招投标与上下游',company_plan:'规划研究',company_collect:'检索与读取',company_clean:'清洗资料',company_extract:'提取企业资料',company_save:'核验保存',company_gap:'分析缺口',company_counterparties:'补齐上下游企业',company_answer:'生成回答'}
const visibleMemories=computed(()=>memories.value.filter((item:any)=>!item.namespace.endsWith('/learned_jobs')))
const SYSTEM_KINDS=['search_experience','company_memory','recipes']
const userMemories=computed(()=>visibleMemories.value.filter((item:any)=>!SYSTEM_KINDS.includes(item.namespace.split('/').at(-1))))
const learnedMemories=computed(()=>visibleMemories.value.filter((item:any)=>SYSTEM_KINDS.includes(item.namespace.split('/').at(-1))))
async function load(){[form.value,health.value,channels.value,memories.value,knowledge.value,graph.value,tracing.value,browser.value,guides.value]=await Promise.all([api('/settings'),api('/health'),api('/channels'),api('/memories'),api('/knowledge'),api('/agent/graph'),api('/tracing'),api('/browser/status'),api('/site-guides')])}
const accessLabels:Record<string,string>={mcp_http:'授权企业查询',mcp_stdio:'公开采购检索',opencli_http:'OpenCLI 接口',opencli_browser:'OpenCLI 浏览器',http:'直接读取',exa:'Exa 检索',http_then_exa:'直接读取，失败改用 Exa',exa_then_http:'Exa 优先'}
const kindLabels:Record<string,string>={aggregator:'招投标聚合',company_hub:'企业招投标主页',original:'原始公告',search:'检索',registry:'第三方名录'}
/** 无参数；只保存服务支持的浏览器策略/预算，不提交任意脚本或执行路径。 */
async function saveBrowser(){await api('/browser/settings','PATCH',browser.value.settings);browser.value=await api('/browser/status');ElMessage.success('已保存')}
/** 无参数；验证用户输入的公开URL，真实失败由API显示，成功不生成虚假的企业或任务。 */
async function testBrowser(){if(!browserUrl.value.trim())return;browserTesting.value=true;browserResult.value=null;try{browserResult.value=await api('/browser/test','POST',{url:browserUrl.value.trim(),backend:browser.value.settings.preferred_backend});browser.value=await api('/browser/status')}finally{browserTesting.value=false}}
const settingFields=['company_name','default_region','max_leads','max_searches','max_reads','model','enabled_channels','max_seconds','max_model_calls','max_model_tokens','max_candidate_searches','research_max_rounds','research_pages_per_query','research_read_concurrency','research_chunks_per_source','research_no_gain_rounds','tender_enabled','tender_detail_reads','tender_reuse_hours','qcc_enabled','max_qcc_calls','bidresearch_enabled','max_bidresearch_calls','bidresearch_max_requests','bidresearch_max_details','bidresearch_timeout','bidresearch_browser']
function channelEnabled(id:string){return id==='qcc_mcp'?form.value.qcc_enabled:id==='bidresearch'?form.value.bidresearch_enabled:form.value.enabled_channels.includes(id)}
function changeChannel(id:string,value:boolean){if(id==='qcc_mcp')form.value.qcc_enabled=value;else if(id==='bidresearch')form.value.bidresearch_enabled=value;else form.value.enabled_channels=value?[...new Set([...form.value.enabled_channels,id])]:form.value.enabled_channels.filter((x:string)=>x!==id)}
async function save(){saving.value=true;try{form.value=await api('/settings','PATCH',Object.fromEntries(settingFields.map(key=>[key,form.value[key]])));channels.value=await api('/channels');ElMessage.success('已保存')}finally{saving.value=false}}
async function test(){testing.value=true;try{testResult.value=await api('/settings/test-model','POST');ElMessage.success('模型连接正常')}finally{testing.value=false}}
async function addMemory(){if(!memoryText.value.trim())return;await api('/memories','POST',{kind:memoryKind.value,content:memoryText.value});memoryDialog.value=false;memoryText.value='';await load()}
async function removeMemory(id:string){await ElMessageBox.confirm('停用这条记忆？','停用');await api('/memories/'+id,'DELETE');await load()}
async function addKnowledge(){if(!knowledgeTitle.value.trim()||!knowledgeBody.value.trim())return;await api('/knowledge','POST',{title:knowledgeTitle.value,body:knowledgeBody.value});knowledgeDialog.value=false;knowledgeTitle.value='';knowledgeBody.value='';await load()}
async function removeKnowledge(id:string){await ElMessageBox.confirm('停用此知识？','停用');await api('/knowledge/'+id,'DELETE');await load()}
async function search(){knowledge.value=await api('/knowledge?q='+encodeURIComponent(query.value))}
function memoryDescription(item:any){const data=item.value;if(data.content)return data.content;if(item.namespace.endsWith('/search_experience'))return `${data.label}：被采用 ${data.adopted}/${data.attempts} 次`;if(item.namespace.endsWith('/company_memory'))return `${data.name} · 有效入口 ${data.useful_urls?.length||0} 个`;if(data.profile)return [data.profile.products?.map((x:any)=>x.name).join('、'),data.profile.region,data.profile.exclusions?.join('、')].filter(Boolean).join(' · ');if(data.channel)return `${data.category} · ${data.region} · ${data.channel}`;return data.name||data.kind||'—'}
onMounted(load)
</script>

<template>
  <div class="page settings-page">
    <el-tabs v-model="section" class="settings-tabs">
      <el-tab-pane name="company" label="工作空间"><section v-if="form" class="settings-section"><div class="section-heading"><h2>我的公司</h2></div><p class="muted section-hint">用于寻找客户时理解你的产品与目标市场。</p><el-form label-position="top" class="settings-form"><el-form-item label="公司名称"><el-input v-model="form.company_name" placeholder="例如：深圳某某照明有限公司"/></el-form-item><el-form-item label="默认目标地区"><el-input v-model="form.default_region" placeholder="例如：深圳"/></el-form-item></el-form><div class="section-heading"><h2>单次任务上限</h2></div><p class="muted section-hint">限制每次查询的耗时与用量，数值越大结果越全但越慢。</p><div class="budget-grid"><label>最多保存客户数<el-input-number v-model="form.max_leads" :min="1" :max="20" aria-label="线索上限"/></label><label>搜索次数<el-input-number v-model="form.max_searches" :min="1" :max="16" aria-label="搜索次数"/></label><label>读取网页总数<el-input-number v-model="form.max_reads" :min="0" :max="24" aria-label="读取次数"/></label><label>最长时间（秒）<el-input-number v-model="form.max_seconds" :min="60" :max="1800" :step="60" aria-label="最长耗时"/></label><label>模型调用次数<el-input-number v-model="form.max_model_calls" :min="1" :max="100" aria-label="模型调用次数"/></label><label>模型用量（tokens）<el-input-number v-model="form.max_model_tokens" :min="4000" :max="1000000" :step="10000" aria-label="模型令牌预算"/></label><label>单个客户补充搜索次数<el-input-number v-model="form.max_candidate_searches" :min="1" :max="8" aria-label="单客户补查次数"/></label></div><div class="section-heading"><h2>企业研究方式</h2></div><p class="muted section-hint">先查招投标平台获取采购、中标与合作关系，再查官网和年报补充企业资料。</p><div class="budget-grid"><label>查询招投标平台<el-switch v-model="form.tender_enabled" aria-label="招投标平台检索"/></label><label>每家企业读取公告数<el-input-number v-model="form.tender_detail_reads" :min="0" :max="16" aria-label="每家企业读取公告详情"/></label><label>已查数据保留时长（小时）<el-input-number v-model="form.tender_reuse_hours" :min="0" :max="720" aria-label="招投标数据复用时长"/></label><label>最多补充查询轮数<el-input-number v-model="form.research_max_rounds" :min="1" :max="8" aria-label="最多研究轮数"/></label><label>每次搜索读取网页数<el-input-number v-model="form.research_pages_per_query" :min="1" :max="8" aria-label="每次搜索读取页数"/></label><label>同时读取网页数<el-input-number v-model="form.research_read_concurrency" :min="1" :max="4" aria-label="网页并发数"/></label><label>每份资料最多分析段数<el-input-number v-model="form.research_chunks_per_source" :min="1" :max="16" aria-label="每份资料分析片段数"/></label><label>连续无新资料时停止（轮）<el-input-number v-model="form.research_no_gain_rounds" :min="1" :max="4" aria-label="无新增资料停止轮数"/></label></div><div class="section-heading"><h2>企业与采购检索额度</h2></div><p class="muted section-hint">采购详情计入读取网页总数；失败和恢复继续使用同一任务额度。渠道开关在“渠道”页设置。</p><div class="budget-grid"><label>工商查询次数<el-input-number v-model="form.max_qcc_calls" :min="0" :max="12" aria-label="工商查询次数"/></label><label>采购检索次数<el-input-number v-model="form.max_bidresearch_calls" :min="0" :max="6" aria-label="采购检索次数"/></label><label>采购请求总数<el-input-number v-model="form.bidresearch_max_requests" :min="0" :max="80" aria-label="采购请求总数"/></label><label>单任务采购详情上限<el-input-number v-model="form.bidresearch_max_details" :min="0" :max="12" aria-label="采购详情数"/></label><label>采购检索超时（秒）<el-input-number v-model="form.bidresearch_timeout" :min="15" :max="180" aria-label="采购检索超时"/></label><label>读取需要浏览器的公开采购站点<el-switch v-model="form.bidresearch_browser" aria-label="采购浏览器读取"/></label></div><el-button type="primary" :loading="saving" @click="save">保存</el-button></section></el-tab-pane>
      <el-tab-pane name="model" label="模型"><section v-if="form" class="settings-section"><h2>模型服务</h2><div class="setting-row"><span>模型</span><strong>{{form.model}}</strong></div><div class="setting-row"><span>连接配置</span><span :class="['connection-state',{ready:form.model_configured}]">{{form.model_configured?'已配置':'未配置'}}</span></div><div class="setting-row"><span>后台任务</span><span :class="['connection-state',{ready:health.worker_online}]">{{health.worker_online?'运行中':'未运行'}}</span></div><el-button :loading="testing" @click="test">测试连接</el-button><div v-if="testResult" class="capabilities"><el-tag v-if="testResult.tool_calling">工具调用</el-tag><el-tag v-if="testResult.structured_output">结构化输出</el-tag><el-tag v-if="testResult.streaming">流式生成</el-tag><span>{{(testResult.elapsed_ms/1000).toFixed(1)}} 秒</span></div></section></el-tab-pane>
      <el-tab-pane name="channels" label="渠道"><section v-if="form" class="settings-section"><div v-for="channel in channels" :key="channel.id" class="channel-row"><div class="channel-info"><strong>{{channel.name}}</strong><small>{{channel.description}}</small><div v-if="['public_index','authorized_mcp','local_mcp'].includes(channel.mode)" class="channel-observations"><span :title="channel.runtime?.search.checked_at||''">搜索：{{channel.runtime?.search.label||'未使用过'}}</span><span :title="channel.runtime?.read.checked_at||''">读取：{{channel.runtime?.read.label||'未使用过'}}</span></div></div><el-switch v-if="channel.status==='ready'" :model-value="channelEnabled(channel.id)" @change="(v:boolean)=>changeChannel(channel.id,v)"/><span v-else class="authorization-label">{{channel.status==='not_installed'?'未安装':'需开通'}}</span></div><el-button type="primary" :loading="saving" @click="save">保存</el-button></section></el-tab-pane>
      <el-tab-pane name="knowledge" label="记忆与知识"><section class="knowledge-section"><div class="section-heading"><h2>长期记忆 <span>{{userMemories.length}}</span></h2><el-button :icon="Plus" @click="memoryDialog=true">添加</el-button></div><div v-for="item in userMemories" :key="item.id" class="memory-row"><span class="memory-kind">{{memoryLabels[item.namespace.split('/').at(-1)]||'记忆'}}</span><div><strong>{{memoryDescription(item)}}</strong><small v-if="item.value.calls">命中 {{item.value.successes}} / {{item.value.calls}} 次</small><small v-else>更新于 {{item.updated_at.slice(0,16)}}</small></div><el-button text :icon="Delete" aria-label="停用记忆" @click="removeMemory(item.id)"/></div><el-empty v-if="!userMemories.length" description="还没有添加记忆" :image-size="70"/><details v-if="learnedMemories.length" class="overview-records additional-records learned-memories"><summary>系统自动积累的经验 · {{learnedMemories.length}} 条</summary><p class="muted section-hint">记录各数据来源是否有用、企业上次的研究入口，用于下次优先选择有效来源。</p><div v-for="item in learnedMemories" :key="item.id" class="memory-row"><span class="memory-kind">{{memoryLabels[item.namespace.split('/').at(-1)]||'记忆'}}</span><div><strong>{{memoryDescription(item)}}</strong><small v-if="item.value.calls">命中 {{item.value.successes}} / {{item.value.calls}} 次</small><small v-else>更新于 {{item.updated_at.slice(0,16)}}</small></div><el-button text :icon="Delete" aria-label="停用记忆" @click="removeMemory(item.id)"/></div></details><div class="section-heading knowledge-heading"><h2>知识库 <span>{{knowledge.active||0}}</span></h2><el-button :icon="Plus" @click="knowledgeDialog=true">添加资料</el-button></div><el-input v-model="query" :prefix-icon="Search" placeholder="搜索知识" clearable @keyup.enter="search" @clear="search" class="knowledge-search"/><div v-for="item in knowledge.items" :key="item.id" class="knowledge-row"><div><strong>{{item.title}}</strong><span :class="['knowledge-status',item.status]">{{item.status==='active'?'有效':item.status==='expired'?'已过期':'已停用'}}</span><p>{{item.body.slice(0,240)}}</p><a v-if="item.source_url" :href="item.source_url" target="_blank" rel="noopener noreferrer">来源 ↗</a><small v-else>产品资料</small></div><el-button text :icon="Delete" aria-label="停用知识" :disabled="item.status!=='active'" @click="removeKnowledge(item.id)"/></div><el-empty v-if="!knowledge.items.length" description="暂无知识" :image-size="70"/></section></el-tab-pane>
      <el-tab-pane name="guides" label="网站指引"><section class="settings-section guide-list"><article v-for="guide in guides" :key="guide.key" class="guide-card"><header><strong>{{guide.name}}</strong><span class="soft-tag">{{kindLabels[guide.kind]||guide.kind}}</span><small>{{accessLabels[guide.access]||guide.access}} · 失败最多尝试 {{guide.retry.max_attempts}} 次<template v-if="guide.login!=='none'"> · {{guide.login==='member'?'需会员登录':'可能出现验证码'}}</template></small></header><p><span class="guide-label">提供</span>{{guide.provides.join('；')}}</p><p v-if="guide.quality_rules.length"><span class="guide-label">质量要求</span>{{guide.quality_rules.join('；')}}</p><p v-if="guide.cautions.length"><span class="guide-label">注意</span>{{guide.cautions.join('；')}}</p></article></section></el-tab-pane>
      <el-tab-pane name="runtime" label="诊断"><section class="settings-section"><div class="setting-row"><span>研究流程版本</span><strong>{{graph.version}}</strong></div><div class="setting-row"><span>中断后继续</span><strong>{{graph.checkpoint?'支持':'—'}}</strong></div><div class="setting-row"><span>研究过程记录</span><strong>{{tracing.enabled?'已开启（LangSmith 项目 '+tracing.project+'）':tracing.configured?'已关闭':'未配置'}}</strong></div><h2>研究步骤</h2><div class="graph-nodes"><span v-for="node in graph.nodes?.filter((n:string)=>!n.startsWith('__'))" :key="node">{{stepLabels[node]||node}}</span></div></section></el-tab-pane>
      <el-tab-pane name="browser" label="网页读取"><section v-if="browser.settings" class="settings-section"><h2>网页读取</h2><p class="muted section-hint">用于打开需要浏览器才能显示的公开网页；遇到登录或验证页面会跳过。</p><div class="setting-row"><span>运行环境</span><span>{{browser.edge_installed&&browser.node_installed?'已安装':'运行时未齐备'}}</span></div><div class="setting-row"><span>读取组件</span><span>{{browser.opencli_installed?'已安装 · '+browser.opencli_version:'未安装'}}</span></div><div class="setting-row"><span>最近一次测试</span><span>{{browser.last_read?.success?'成功 · '+browser.last_read.checked_at:'未测试'}}</span></div><el-form label-position="top" class="settings-form"><el-form-item label="启用"><el-switch v-model="browser.settings.enabled"/></el-form-item><el-form-item label="读取方式"><el-select v-model="browser.settings.preferred_backend"><el-option label="自动选择（推荐）" value="auto"/><el-option label="OpenCLI" value="opencli"/><el-option label="Playwright" value="playwright"/></el-select></el-form-item><el-form-item label="每次任务最多打开网页数"><el-input-number v-model="browser.settings.max_pages" :min="1" :max="8"/></el-form-item><el-form-item label="每页最多读取字数"><el-input-number v-model="browser.settings.max_chars" :min="2000" :max="100000" :step="2000"/></el-form-item><el-form-item label="单页超时（秒）"><el-input-number v-model="browser.settings.command_timeout" :min="15" :max="120"/></el-form-item></el-form><el-button @click="saveBrowser">保存</el-button><h2 style="margin-top:28px">测试读取</h2><el-input v-model="browserUrl" placeholder="输入公开网页地址 https://…" aria-label="公开网页地址" style="margin-top:15px"/><el-button :loading="browserTesting" :disabled="!browserUrl.trim()" @click="testBrowser">测试读取</el-button><div v-if="browserResult" class="coverage-card"><strong>{{browserResult.title}}</strong><p>{{browserResult.body_chars}} 字符 · {{browserResult.backend}} · {{(browserResult.elapsed_ms/1000).toFixed(1)}} 秒</p><pre class="source-body">{{browserResult.preview}}</pre></div></section></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="memoryDialog" title="添加记忆" width="520px"><el-select v-model="memoryKind"><el-option label="公司信息" value="company"/><el-option label="偏好" value="preference"/><el-option label="排除条件" value="exclusion"/></el-select><el-input v-model="memoryText" type="textarea" :rows="5" placeholder="例如：我们主营 LED 灯具；不要推荐同行企业" class="note-input"/><template #footer><el-button @click="memoryDialog=false">取消</el-button><el-button type="primary" @click="addMemory">保存</el-button></template></el-dialog>
    <el-dialog v-model="knowledgeDialog" title="添加资料" width="600px"><el-input v-model="knowledgeTitle" placeholder="资料名称"/><el-input v-model="knowledgeBody" type="textarea" :rows="8" placeholder="粘贴产品介绍、价格表或公司资料" class="note-input"/><template #footer><el-button @click="knowledgeDialog=false">取消</el-button><el-button type="primary" @click="addKnowledge">保存</el-button></template></el-dialog>
  </div>
</template>
